#define RN 4
typedef struct { int buf[RN]; int head; int count; long sum; } ring_t;

int ring_push(ring_t *r, int v) {
    if (r->count == RN) r->sum -= r->buf[r->head];
    else r->count++;
    r->buf[r->head] = v;
    r->sum += v;
    r->head = (r->head + 1) % RN;
    return r->sum / r->count;
}

