const uint32_t MIN_SWITCH_MS = 1000;
bool motor_on = false;
uint32_t last_switch = 0;
int switch_count = 0;

bool relay_request(bool on) {
    if (on == motor_on) return true;
    if (switch_count > 0 && millis() - last_switch < MIN_SWITCH_MS) {
        Serial.print("무시 ");  return false;
    }
    relay_set(on);  motor_on = on;
    last_switch = millis();  switch_count++;
    Serial.print(on ? "ON " : "OFF ");
    return true;
}

